<div class="main-content"><?php require APP_ROOT.'/app/views/components/navbar.php';?><div class="content-wrapper"><div class="d-flex justify-content-between mb-3"><div><h5 class="mb-1">Incident Report</h5><p class="text-muted mb-0">Incident status and priority across your house.</p></div><a class="btn btn-outline-primary btn-sm" href="<?=url('views/houseparent/incidents/index.php')?>">Open incident log</a></div><div class="row g-3 mb-3"><div class="col-md-4"><div class="card stat-card p-3"><small class="text-muted">Total</small><strong class="fs-2"><?=e((string)count($incidents))?></strong></div></div><div class="col-md-4"><div class="card stat-card p-3"><small class="text-muted">Open</small><strong class="fs-2 text-warning"><?=e((string)count(array_filter($incidents,fn($i)=>($i['status']??'open')==='open')))?></strong></div></div><div class="col-md-4"><div class="card stat-card p-3"><small class="text-muted">Resolved</small><strong class="fs-2 text-success"><?=e((string)count(array_filter($incidents,fn($i)=>($i['status']??'')==='resolved')))?></strong></div></div></div><div class="card stat-card p-3"><table class="table table-hover"><thead><tr><th>Student</th><th>Title</th><th>Priority</th><th>Status</th></tr></thead><tbody><?php foreach($incidents as $incident):$student=$map[(string)($incident['studentId']??'')]??[];?><tr><td><?=e(trim(($student['firstName']??'').' '.($student['lastName']??''))?:($incident['studentId']??'-'))?></td><td><?=e($incident['title']??'Incident')?></td><td><?=e($incident['priority']??'medium')?></td><td><?=e($incident['status']??'open')?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require APP_ROOT.'/app/views/components/footer.php';?>